@import "tailwindcss";

@theme {
  --font-sans: var(--font-space-grotesk), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-jetbrains-mono), monospace;
  --font-display: var(--font-space-grotesk), ui-sans-serif, system-ui, sans-serif;

  /* Sleek Modern Palette */
  --color-background-dark: #09090b;
  /* Zinc 950 */
  --color-background-black: #09090b;
  /* Replaced true black with deep charcoal */
  --color-background-light: #18181b;
  /* Zinc 900 */

  /* Sophisticated Accents */
  --color-primary: #3b82f6;
  --color-primary-glow: rgba(59, 130, 246, 0.3);

  --color-accent-cyan: #00D9FF;
  --color-accent-gold: #D4AF37;
  --color-accent-blue: #3b82f6;
  --color-destructive: #ef4444;

  --color-text-main: #ededed;
  --color-text-muted: #71717a;

  /* Glassmorphism Refined */
  --color-glass-bg: rgba(255, 255, 255, 0.02);
  --color-glass-border: rgba(255, 255, 255, 0.06);
}

@layer base {
  html {
    scroll-behavior: smooth;
  }

  body {
    @apply text-text-main font-sans min-h-screen flex flex-col antialiased overflow-x-hidden;
    background: transparent;
  }

  .bg-background-black {
    background-color: var(--color-background-black);
  }
}

@layer utilities {
  .glass-panel {
    @apply bg-glass-bg border border-glass-border backdrop-blur-xl rounded-2xl shadow-2xl transition-all duration-300;
  }

  .text-glow {
    text-shadow: 0 0 20px var(--color-primary-glow);
  }

